#include <iostream>
#include <string>
#include <vector>
int main() {
    std::string pending;
    for (const std::string& chunk : std::vector<std::string>{"HE", "LLO\nBY", "E\n"}) {
        pending += chunk; // Model byte arrivals, not TCP packet boundaries.
        std::size_t end;
        while ((end = pending.find('\n')) != std::string::npos) {
            std::cout << pending.substr(0, end) << '\n';
            pending.erase(0, end + 1);
        }
    }
    std::cout << "tail=" << pending.size() << '\n';
}

#include <algorithm>
#include <array>
#include <iostream>
#include <string>
int main() {
    const std::string payload = "A\nB";
    const std::string delimited = payload + '\n';
    std::cout << "delimiter messages="
              << std::count(delimited.begin(), delimited.end(), '\n') << '\n';
    const std::array<unsigned char, 5> frame{0, 3, 'A', '\n', 'B'};
    const unsigned length = (unsigned(frame[0]) << 8) | frame[1];
    std::cout << "length payload bytes=" << length << '\n';
}

